252	    private void OnYarnDialogueComplete()
253	    {
254	        _dialogueState.CurrentPhase = DialoguePhase.Complete;
255	        DeactivateDialogue();
256	    }
257	
258	    // --- Dialogue start trigger (from NPCInteractionSystem) ---
259	
260	    [Subscribe]
261	    private void OnDialogueStart(in DialogueStartMessage message)
262	    {
263	        if (_dialogueState.IsActive) return;
264	        StartYarnDialogue(message.StartNode);
265	    }
266	
267	    // --- Collision trigger ---
268	
269	    [Subscribe]
270	    private void OnCollision(in CollisionMessage message)
271	    {
272	        if (message.Type != CollisionType.Dialogue) return;
273	        if (_dialogueState.IsActive || _dialogueState.WasTriggered) return;
274	
275	        var zoneEntity = message.CollidingEntity;
276	        var nodeName = "HelloWorld";
277	
278	        if (zoneEntity.Has<DialogueZoneComponent>())
279	        {
280	            var zone = zoneEntity.Get<DialogueZoneComponent>();
281	            if (zone.OneTimeOnly && zone.HasBeenTriggered) return;
282	            nodeName = zone.YarnNodeName;
283	            zone.HasBeenTriggered = true;
284	        }
285	
286	        StartYarnDialogue(nodeName);
287	    }
288	
289	    public void StartYarnDialogue(string nodeName)
290	    {
291	        _dialogueState.IsActive = true;
292	        _dialogueState.WasTriggered = true;
293	
294	        // The Interact press that opened this dialogue may still be held this same
295	        // frame. Consume the edge so DialogueSystem.Update (later in this tick)
296	        // doesn't read JustPressed and advance the first line on its own opening.
297	        InputState.Interact.Consume();
298	
299	        // Show dialogue box
300	        _dialogueState.BoxEntity.Set<Visible>();
301	
302	        _world.Publish(new DialogueActiveMessage(true));
303	
304	        // Start the yarn node — fires LineHandler or OptionsHandler synchronously
305	        _yarnDialogue.SetNode(nodeName);
306	        _yarnDialogue.Continue();
307	    }
308	
309	    // --- Update loop ---
310	
311	    public void Update(GameState state)
312	    {
313	        if (!_dialogueState.IsActive) return;
314	
315	        switch (_dialogueState.CurrentPhase)
316	        {
317	            case DialoguePhase.Line:
318	                UpdateLinePhase(InputState.Interact.JustPressed());
319	                break;
320	            case DialoguePhase.Options:
321	                UpdateOptionsPhase(
322	                    InputState.Up.JustPressed(),
323	                    InputState.Down.JustPressed(),
324	                    InputState.Interact.JustPressed());
325	                break;
326	        }
327	    }
328	
329	    private void UpdateLinePhase(bool interactJustPressed)
330	    {
331	        ref var dynamicText = ref _dialogueState.TextEntity.Get<DynamicText>();
332	
333	        if (dynamicText.IsRevealed)
334	        {
335	            if (!_dialogueState.IndicatorEntity.Has<Visible>())
336	                _dialogueState.IndicatorEntity.Set<Visible>();
337	            _dialogueState.WaitingForInput = true;
338	        }
339	        else
340	        {
341	            HideIndicator();
342	        }
343	
344	        if (!interactJustPressed) return;
345	
346	        if (!dynamicText.IsRevealed)
347	        {
348	            // Skip reveal — show all text immediately
349	            dynamicText.VisibleCharacterCount = dynamicText.TextContent?.Length ?? 0;
350	            dynamicText.IsRevealed = true;
351	        }
352	        else
353	        {
354	            // Advance to next yarn content
355	            _yarnDialogue.Continue();
356	        }
357	    }
358	
359	    private void UpdateOptionsPhase(bool upJustPressed, bool downJustPressed, bool interactJustPressed)
360	    {
361	        if (upJustPressed)
362	        {
363	            _dialogueState.SelectedOptionIndex =
364	                Math.Max(0, _dialogueState.SelectedOptionIndex - 1);
365	            UpdateOptionHighlights();
366	        }
367	        else if (downJustPressed)
368	        {
369	            _dialogueState.SelectedOptionIndex =
370	                Math.Min(_dialogueState.CurrentOptions.Count - 1, _dialogueState.SelectedOptionIndex + 1);
371	            UpdateOptionHighlights();
372	        }
373	
374	        if (interactJustPressed)
375	        {
376	            var yarnOptionID = _dialogueState.CurrentOptionIDs[_dialogueState.SelectedOptionIndex];
377	            HideOptions();
378	            _yarnDialogue.SetSelectedOption(yarnOptionID);
379	            _yarnDialogue.Continue();
380	        }
381	    }
382	
383	    // --- Option entity management ---
384	
385	    private void ShowOptions()
386	    {
387	        HideOptions();
388	
389	        const float startY = 16f;
390	        const float optionSpacing = 24f;
391	
392	        for (var i = 0; i < _dialogueState.CurrentOptions.Count; i++)
393	        {
394	            var prefix = i == _dialogueState.SelectedOptionIndex ? "> " : "  ";
395	            var fullText = prefix + _dialogueState.CurrentOptions[i];
396	
397	            var optionEntity = _world.CreateEntity();
398	            optionEntity.Set(new EntityInfo(nameof(EntityType.Interface), $"DialogueOption{i}"));
399	            optionEntity.Set(new Transform(new Vector2(16, startY + i * optionSpacing)));
400	            optionEntity.SetParent(_rootEntity);
401	            optionEntity.Set(new DynamicText
402	            {
403	                Target = RenderTargetID.UI,
404	                LayerDepth = _layers.GetDepth(GameDrawLayer.DialogueUI, +0.01f),
405	                Font = _font,
406	                Color = i == _dialogueState.SelectedOptionIndex ? Color.White : Color.SaddleBrown,
407	                Scale = 0.5f,
408	                RevealingSpeed = 0, // Instant reveal
409	                RevealStartTime = 0,
410	                IsRevealed = true,
411	                VisibleCharacterCount = fullText.Length,
412	                TextContent = fullText
413	            });
414	            optionEntity.Set(new DrawComponent
415	            {
416	                Type = DrawElementType.Text,
417	                Target = RenderTargetID.UI
418	            });
419	            optionEntity.Set<Visible>();
420	
421	            _dialogueState.OptionEntities.Add(optionEntity);
422	        }
423	    }
424	
425	    private void UpdateOptionHighlights()
426	    {
427	        for (var i = 0; i < _dialogueState.OptionEntities.Count; i++)
428	        {
429	            var entity = _dialogueState.OptionEntities[i];
430	            if (!entity.IsAlive) continue;
431	
432	            ref var dt = ref entity.Get<DynamicText>();
433	            var prefix = i == _dialogueState.SelectedOptionIndex ? "> " : "  ";
434	            dt.TextContent = prefix + _dialogueState.CurrentOptions[i];
435	            dt.VisibleCharacterCount = dt.TextContent.Length;
436	            dt.Color = i == _dialogueState.SelectedOptionIndex ? Color.White : Color.SaddleBrown;
437	        }
438	    }
439	
440	    private void HideOptions()
441	    {
442	        foreach (var entity in _dialogueState.OptionEntities)
443	        {
444	            if (entity.IsAlive) entity.Dispose();
445	        }
446	        _dialogueState.OptionEntities.Clear();
447	    }
448	
449	    private void HideIndicator()
450	    {
451	        if (_dialogueState.IndicatorEntity.Has<Visible>())
452	            _dialogueState.IndicatorEntity.Remove<Visible>();
453	    }
454	
455	    // --- Deactivation ---
456	
457	    private void DeactivateDialogue()
458	    {
459	        _dialogueState.IsActive = false;
460	        _dialogueState.WasTriggered = false;
461	        _dialogueState.CurrentPhase = DialoguePhase.None;
462	        _dialogueState.WaitingForInput = false;
463	        _dialogueState.CurrentSpeaker = null;
464	
465	        HideOptions();
466	
467	        // Hide box
468	        if (_dialogueState.BoxEntity.Has<Visible>())
469	            _dialogueState.BoxEntity.Remove<Visible>();
470	
471	        var boxDraw = _dialogueState.BoxEntity.Get<DrawComponent>();
472	        boxDraw.Texture = null;
473	
474	        // Clear text
475	        ref var dynamicText = ref _dialogueState.TextEntity.Get<DynamicText>();
476	        dynamicText.VisibleCharacterCount = 0;
477	        dynamicText.IsRevealed = false;
478	        dynamicText.TextContent = "";
479	
480	        var textDraw = _dialogueState.TextEntity.Get<DrawComponent>();
481	        textDraw.Text = null;
482	        textDraw.Font = null;
483	
484	        // Hide indicator
485	        HideIndicator();
486	        var indicatorDraw = _dialogueState.IndicatorEntity.Get<DrawComponent>();
487	        indicatorDraw.Texture = null;
488	
489	        _world.Publish(new DialogueActiveMessage(false));
490	    }
491	
492	    public void Dispose()
493	    {
494	        GC.SuppressFinalize(this);
495	    }
496	}
